import sqlite3
import json
import hashlib
from contextlib import contextmanager
from datetime import date

SCHEMA = """
CREATE TABLE IF NOT EXISTS opportunity (
    id INTEGER PRIMARY KEY,
    source TEXT NOT NULL,
    source_key TEXT NOT NULL,
    payload_sha TEXT NOT NULL,
    score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),
    state TEXT NOT NULL DEFAULT 'staged'
        CHECK(state IN ('staged', 'verified', 'held', 'accepted')),
    UNIQUE(source, source_key)
);
CREATE TABLE IF NOT EXISTS transition_event (
    event_key TEXT PRIMARY KEY,
    opportunity_id INTEGER NOT NULL REFERENCES opportunity(id),
    request_sha TEXT NOT NULL,
    actor TEXT NOT NULL,
    evidence_json TEXT NOT NULL,
    from_state TEXT NOT NULL,
    to_state TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS invoice (
    id INTEGER PRIMARY KEY,
    invoice_key TEXT NOT NULL UNIQUE,
    opportunity_id INTEGER NOT NULL REFERENCES opportunity(id),
    milestone_key TEXT NOT NULL,
    booked_on TEXT NOT NULL,
    amount_cents INTEGER NOT NULL
        CHECK(typeof(amount_cents) = 'integer' AND amount_cents > 0),
    UNIQUE(opportunity_id, milestone_key)
);
CREATE TABLE IF NOT EXISTS journal (
    id INTEGER PRIMARY KEY,
    event_key TEXT NOT NULL UNIQUE,
    invoice_id INTEGER REFERENCES invoice(id),
    booked_on TEXT NOT NULL,
    debit TEXT NOT NULL,
    credit TEXT NOT NULL,
    amount_cents INTEGER NOT NULL
        CHECK(typeof(amount_cents) = 'integer' AND amount_cents > 0),
    currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency = 'USD'),
    CHECK(
        (debit = 'ar' AND credit = 'service_revenue'
            AND invoice_id IS NOT NULL)
        OR
        (debit = 'cash' AND credit = 'ar'
            AND invoice_id IS NOT NULL)
        OR
        (debit = 'expense' AND credit = 'cash'
            AND invoice_id IS NULL)
        OR
        (debit = 'cash' AND credit = 'owner_capital'
            AND invoice_id IS NULL)
    )
);
CREATE UNIQUE INDEX IF NOT EXISTS one_revenue_posting
ON journal(invoice_id) WHERE credit = 'service_revenue';

CREATE TRIGGER IF NOT EXISTS journal_no_update
BEFORE UPDATE ON journal BEGIN
    SELECT RAISE(ABORT, 'journal entries are immutable');
END;
CREATE TRIGGER IF NOT EXISTS journal_no_delete
BEFORE DELETE ON journal BEGIN
    SELECT RAISE(ABORT, 'journal entries are immutable');
END;
CREATE TRIGGER IF NOT EXISTS invoice_no_update
BEFORE UPDATE ON invoice BEGIN
    SELECT RAISE(ABORT, 'invoices are immutable');
END;
CREATE TRIGGER IF NOT EXISTS invoice_no_delete
BEFORE DELETE ON invoice BEGIN
    SELECT RAISE(ABORT, 'invoices are immutable');
END;
CREATE TRIGGER IF NOT EXISTS transition_no_update
BEFORE UPDATE ON transition_event BEGIN
    SELECT RAISE(ABORT, 'transition evidence is immutable');
END;
CREATE TRIGGER IF NOT EXISTS transition_no_delete
BEFORE DELETE ON transition_event BEGIN
    SELECT RAISE(ABORT, 'transition evidence is immutable');
END;
CREATE TRIGGER IF NOT EXISTS revenue_matches_invoice
BEFORE INSERT ON journal WHEN NEW.credit = 'service_revenue'
BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM invoice
        WHERE id = NEW.invoice_id
          AND amount_cents = NEW.amount_cents
          AND booked_on = NEW.booked_on
    ) THEN RAISE(ABORT, 'revenue must match invoice') END;
END;
CREATE TRIGGER IF NOT EXISTS collection_within_balance
BEFORE INSERT ON journal WHEN NEW.credit = 'ar'
BEGIN
    SELECT CASE WHEN NEW.amount_cents > COALESCE((
        SELECT SUM(CASE
            WHEN debit = 'ar' THEN amount_cents
            WHEN credit = 'ar' THEN -amount_cents
            ELSE 0 END)
        FROM journal WHERE invoice_id = NEW.invoice_id
    ), 0) THEN RAISE(ABORT, 'collection exceeds receivable') END;
END;
"""

def open_db(path, initialize=True):
    db = sqlite3.connect(path, timeout=30, isolation_level=None)
    db.execute("PRAGMA foreign_keys = ON")
    db.execute("PRAGMA busy_timeout = 30000")
    if initialize:
        db.execute("PRAGMA journal_mode = WAL")
        db.executescript(SCHEMA)
    return db

@contextmanager
def atomic(db):
    if db.in_transaction:
        raise RuntimeError("nested business transaction rejected")
    db.execute("BEGIN IMMEDIATE")
    try:
        yield
        db.commit()
    except BaseException:
        db.rollback()
        raise

def packed(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"))

def digest(value):
    return hashlib.sha256(packed(value).encode("utf-8")).hexdigest()

def required_text(value):
    if not isinstance(value, str) or not value.strip():
        raise ValueError("nonempty text required")
    return value

def cents(value):
    if type(value) is not int or value <= 0:
        raise ValueError("positive integer cents required")
    return value

def day(value):
    required_text(value)
    if date.fromisoformat(value).isoformat() != value:
        raise ValueError("canonical calendar date required")
    return value

TRANSITIONS = {
    "staged": {"verified", "held"},
    "verified": {"accepted", "held"},
    "held": {"verified"},
    "accepted": set(),
}

def advance(db, event_key, opportunity_id, expected, target, actor, evidence):
    required_text(event_key)
    required_text(actor)
    if not isinstance(evidence, dict):
        raise ValueError("structured evidence required")
    required_text(evidence.get("evidence_ref"))
    if target == "verified":
        checks = ("eligibility_checked", "fee_structure_checked", "conflicts_checked")
        if any(evidence.get(item) is not True for item in checks):
            raise ValueError("verification evidence incomplete")
    if target == "accepted":
        required_text(evidence.get("client_acceptance_ref"))
    request = digest({
        "opportunity_id": opportunity_id,
        "expected": expected,
        "target": target,
        "actor": actor,
        "evidence": evidence,
    })
    with atomic(db):
        prior = db.execute(
            "SELECT request_sha FROM transition_event WHERE event_key = ?",
            (event_key,),
        ).fetchone()
        if prior:
            if prior[0] != request:
                raise ValueError("transition key reused with altered content")
            return
        row = db.execute(
            "SELECT state FROM opportunity WHERE id = ?",
            (opportunity_id,),
        ).fetchone()
        if row is None or row[0] != expected:
            raise ValueError("stale or missing workflow state")
        if target not in TRANSITIONS.get(expected, set()):
            raise ValueError("transition prohibited")
        db.execute(
            "UPDATE opportunity SET state = ? WHERE id = ?",
            (target, opportunity_id),
        )
        db.execute(
            "INSERT INTO transition_event "
            "(event_key, opportunity_id, request_sha, actor, evidence_json, "
            "from_state, to_state) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (event_key, opportunity_id, request, actor, packed(evidence),
             expected, target),
        )
